  private static final class JsonOnlyServer implements AutoCloseable {
    final ServerSocket server;final Thread worker;final List<JSONObject> requests=Collections.synchronizedList(new ArrayList<>());final AtomicReference<Throwable> error=new AtomicReference<>();
    JsonOnlyServer()throws Exception{
      server=new ServerSocket(0,4,InetAddress.getByName("127.0.0.1"));worker=new Thread(()->{try{while(!server.isClosed()){try(Socket socket=server.accept()){socket.setSoTimeout(10000);InputStream in=socket.getInputStream();ByteArrayOutputStream header=new ByteArrayOutputStream();int last=0;while(header.size()<65536){int value=in.read();if(value<0)throw new EOFException("Mock header incomplete");header.write(value);last=(last<<8)|value;if(last==0x0d0a0d0a)break;}String fields=header.toString("US-ASCII");VoiceSupport.check(fields.startsWith("POST /chat/completions ")&&fields.toLowerCase(Locale.ROOT).contains("content-type: application/json"),"Only text JSON chat reaches the configured mock, never an audio transcription route");int length=-1;for(String line:fields.split("\\r\\n"))if(line.toLowerCase(Locale.ROOT).startsWith("content-length:"))length=Integer.parseInt(line.substring(line.indexOf(':')+1).trim());VoiceSupport.check(length>=0&&length<1048576,"Bounded fixed JSON body");byte[] bytes=new byte[length];for(int offset=0;offset<length;){int count=in.read(bytes,offset,length-offset);if(count<0)throw new EOFException("Mock body incomplete");offset+=count;}JSONObject body=new JSONObject(new String(bytes,StandardCharsets.UTF_8));requests.add(body);
        JSONObject memory=new JSONObject().put("title","去买咖啡").put("content",EDITED).put("kind","intent").put("type","task").put("status","active").put("tags",new JSONArray().put("生活")).put("temporal",new JSONObject().put("raw","明天下午三点").put("source","user"));
        JSONObject result=new JSONObject().put("intent","record").put("reply","这件事记着了。").put("memories",new JSONArray().put(memory)).put("updates",new JSONArray());JSONObject response=new JSONObject().put("choices",new JSONArray().put(new JSONObject().put("message",new JSONObject().put("content",result.toString()))));byte[] out=response.toString().getBytes(StandardCharsets.UTF_8);OutputStream output=socket.getOutputStream();output.write(("HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: "+out.length+"\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.US_ASCII));output.write(out);output.flush();
      }}}catch(Throwable problem){if(!server.isClosed())error.set(problem);}},"voice-text-only-fixture");worker.setDaemon(true);worker.start();
    }
    String url(){return "http://127.0.0.1:"+server.getLocalPort();}
    void verify(int expected)throws Exception{VoiceSupport.check(error.get()==null,"Observed mock request error: "+error.get());VoiceSupport.check(requests.size()==expected,"Expected exactly "+expected+" text requests, received "+requests.size());synchronized(requests){for(JSONObject request:requests){String body=request.toString();VoiceSupport.check(!body.contains(RAW_MARKER)&&!body.contains("input_audio")&&!body.contains("audio_url")&&!body.contains("data:audio")&&!body.contains("base64"),"Original audio and unedited recognizer text must be absent from the model request");JSONArray messages=request.getJSONArray("messages");Object content=messages.getJSONObject(messages.length()-1).get("content");VoiceSupport.check(content instanceof String,"A text-only model receives a text user content");JSONObject context=new JSONObject((String)content);VoiceSupport.check(context.getString("本次用户原话").equals(EDITED)&&context.getString("本次原时日期").equals("2033-03-28")&&context.getString("本次原时时区").equals(ZONE),"Only edited input reaches the AI with the original voice date and zone");}}}
    @Override public void close()throws Exception{server.close();worker.join(2000);}
  }
